var DICE_FIELD_DISPLAY_ICON_SIDES = [4, 6, 8, 10, 12, 20];
var DEFAULT_ICON_SIDES = 6;
var MAX_DISPLAY_TEXT_LENGTH = 40;
function isDiceFieldDisplayIconSides(value) {
  return typeof value === "number" && DICE_FIELD_DISPLAY_ICON_SIDES.includes(value);
}
function getDiceFieldDisplaySettings(field) {
  const mode = field.diceDisplayMode === "icon" || field.diceDisplayMode === "text" ? field.diceDisplayMode : "formula";
  return {
    mode,
    iconSides: isDiceFieldDisplayIconSides(field.diceDisplayIconSides) ? field.diceDisplayIconSides : DEFAULT_ICON_SIDES,
    text: typeof field.diceDisplayText === "string" ? field.diceDisplayText.slice(0, MAX_DISPLAY_TEXT_LENGTH) : ""
  };
}
function setDiceFieldDisplayMode(field, mode) {
  if (mode === "formula") {
    delete field.diceDisplayMode;
    delete field.diceDisplayIconSides;
    delete field.diceDisplayText;
    return;
  }
  field.diceDisplayMode = mode;
  if (mode === "icon") {
    delete field.diceDisplayText;
    if (!isDiceFieldDisplayIconSides(field.diceDisplayIconSides)) {
      field.diceDisplayIconSides = DEFAULT_ICON_SIDES;
    }
  } else {
    delete field.diceDisplayIconSides;
  }
}
function setDiceFieldDisplayIconSides(field, sides) {
  if (!isDiceFieldDisplayIconSides(sides)) return false;
  field.diceDisplayMode = "icon";
  field.diceDisplayIconSides = sides;
  delete field.diceDisplayText;
  return true;
}
function setDiceFieldDisplayText(field, text4) {
  field.diceDisplayMode = "text";
  field.diceDisplayText = text4.slice(0, MAX_DISPLAY_TEXT_LENGTH);
  delete field.diceDisplayIconSides;
}

