var COUNTER_PIP_DISPLAY_MAX = 10;
function counterUsesNumericDisplay(maximum) {
  return Number.isFinite(maximum) && maximum > COUNTER_PIP_DISPLAY_MAX;
}
function shouldShowCounterNumericValue(showCounterValue, maximum) {
  return showCounterValue || counterUsesNumericDisplay(maximum);
}
function shouldEnableCounterNumericValues(rows) {
  return rows.some((row) => {
    if (typeof row !== "object" || row === null || Array.isArray(row)) return false;
    const maximum = row.max;
    return typeof maximum === "number" && counterUsesNumericDisplay(maximum);
  });
}

